import java.util.concurrent.*; class IntHolder { private int value; public synchronized int get() { return value; } public synchronized void set(int v) { value = v; } } public class Main { public static void main(String[] args) throws Exception { IntHolder holder = new IntHolder(); ExecutorService es = Executors.newFixedThreadPool(2); es.execute(() -> { holder.set(1); }); es.execute(() -> { holder.get(); }); es.shutdown(); es.awaitTermination(1, TimeUnit.SECONDS); } }
